export type EventHandler<T = any> = (payload: T) => void;

export class EventBus {
  private subscribers: Map<string, Set<EventHandler>> = new Map();

  subscribe<T = any>(eventName: string, handler: EventHandler<T>): () => void {
    if (!this.subscribers.has(eventName)) {
      this.subscribers.set(eventName, new Set());
    }
    const set = this.subscribers.get(eventName)!;
    set.add(handler as EventHandler);
    return () => {
      set.delete(handler as EventHandler);
    };
  }

  publish<T = any>(eventName: string, payload: T): void {
    const set = this.subscribers.get(eventName);
    if (!set) return;
    for (const handler of set) {
      try {
        handler(payload);
      } catch (err) {
        // Swallow handler errors to avoid breaking the bus
        console.error(`Error in handler for event '${eventName}':`, err);
      }
    }
  }
}

export type TaskStatus = 'todo' | 'in-progress' | 'done';

// Event payload types (for convenience across services)
export interface TaskAssignedEvent {
  taskId: string;
  assigneeId: string;
  projectId: string;
  title: string;
}

export interface TaskStatusChangedEvent {
  taskId: string;
  from: TaskStatus;
  to: TaskStatus;
  assigneeId?: string;
  projectId: string;
  title: string;
}

export interface TaskDeletedEvent {
  taskId: string;
  assigneeId?: string;
  projectId: string;
  title: string;
}

export interface TaskCreatedEvent {
  taskId: string;
  projectId: string;
  assigneeId?: string;
  title: string;
}

export interface CommentAddedEvent {
  commentId: string;
  taskId: string;
  authorId: string;
  text: string;
}

export interface User {
  id: string;
  name: string;
  email: string;
}

export class UserService {
  private users: Map<string, User> = new Map();

  list(): User[] {
    return Array.from(this.users.values());
  }

  get(id: string): User | undefined {
    return this.users.get(id);
  }

  create(input: { name: string; email: string }): User {
    const id = this.generateId();
    const user: User = { id, name: input.name, email: input.email };
    this.users.set(id, user);
    return user;
  }

  update(id: string, input: Partial<Omit<User, 'id'>>): User | undefined {
    const user = this.users.get(id);
    if (!user) return undefined;
    const updated: User = { ...user, ...input, id };
    this.users.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.users.delete(id);
  }

  private generateId(): string {
    return Math.random().toString(36).slice(2) + Date.now().toString(36);
  }
}

export interface Project {
  id: string;
  name: string;
  description?: string;
  members: string[]; // user IDs
}

export class ProjectService {
  private projects: Map<string, Project> = new Map();

  list(): Project[] {
    return Array.from(this.projects.values());
  }

  get(id: string): Project | undefined {
    return this.projects.get(id);
  }

  create(input: { name: string; description?: string; members?: string[] }): Project {
    const id = this.generateId();
    const project: Project = {
      id,
      name: input.name,
      description: input.description,
      members: input.members ? Array.from(new Set(input.members)) : [],
    };
    this.projects.set(id, project);
    return project;
  }

  update(id: string, input: Partial<Omit<Project, 'id'>>): Project | undefined {
    const existing = this.projects.get(id);
    if (!existing) return undefined;
    const updated: Project = {
      ...existing,
      ...input,
      id,
      members: input.members ? Array.from(new Set(input.members)) : existing.members,
    };
    this.projects.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.projects.delete(id);
  }

  addMember(projectId: string, userId: string): Project | undefined {
    const project = this.projects.get(projectId);
    if (!project) return undefined;
    if (!project.members.includes(userId)) project.members.push(userId);
    return project;
  }

  removeMember(projectId: string, userId: string): Project | undefined {
    const project = this.projects.get(projectId);
    if (!project) return undefined;
    project.members = project.members.filter((m) => m !== userId);
    return project;
  }

  private generateId(): string {
    return Math.random().toString(36).slice(2) + Date.now().toString(36);
  }
}

import { EventBus, TaskStatus, TaskAssignedEvent, TaskStatusChangedEvent, TaskCreatedEvent, TaskDeletedEvent } from '../event-bus';

export interface Task {
  id: string;
  title: string;
  description?: string;
  status: TaskStatus;
  assigneeId?: string; // user ID
  projectId: string;
}

export class TaskService {
  private tasks: Map<string, Task> = new Map();
  private bus: EventBus;

  constructor(bus: EventBus) {
    this.bus = bus;
  }

  list(filter?: { projectId?: string }): Task[] {
    let arr = Array.from(this.tasks.values());
    if (filter?.projectId) arr = arr.filter((t) => t.projectId === filter.projectId);
    return arr;
  }

  get(id: string): Task | undefined {
    return this.tasks.get(id);
  }

  create(input: { title: string; description?: string; assigneeId?: string; projectId: string }): Task {
    const id = this.generateId();
    const task: Task = {
      id,
      title: input.title,
      description: input.description,
      status: 'todo',
      assigneeId: input.assigneeId,
      projectId: input.projectId,
    };
    this.tasks.set(id, task);
    const event: TaskCreatedEvent = { taskId: id, projectId: task.projectId, assigneeId: task.assigneeId, title: task.title };
    this.bus.publish('task.created', event);
    if (task.assigneeId) {
      const assignedEvent: TaskAssignedEvent = { taskId: id, assigneeId: task.assigneeId, projectId: task.projectId, title: task.title };
      this.bus.publish('task.assigned', assignedEvent);
    }
    return task;
  }

  update(id: string, input: Partial<Omit<Task, 'id' | 'status' | 'projectId'>>): Task | undefined {
    const existing = this.tasks.get(id);
    if (!existing) return undefined;
    const updated: Task = { ...existing, ...input, id };
    this.tasks.set(id, updated);
    if (existing.assigneeId !== updated.assigneeId && updated.assigneeId) {
      const assignedEvent: TaskAssignedEvent = { taskId: id, assigneeId: updated.assigneeId, projectId: updated.projectId, title: updated.title };
      this.bus.publish('task.assigned', assignedEvent);
    }
    return updated;
  }

  delete(id: string): boolean {
    const existing = this.tasks.get(id);
    if (!existing) return false;
    this.tasks.delete(id);
    const event: TaskDeletedEvent = { taskId: id, assigneeId: existing.assigneeId, projectId: existing.projectId, title: existing.title };
    this.bus.publish('task.deleted', event);
    return true;
  }

  setStatus(id: string, to: TaskStatus): Task | undefined {
    const task = this.tasks.get(id);
    if (!task) return undefined;
    const from = task.status;
    if (!this.isValidTransition(from, to)) return undefined;
    task.status = to;
    const event: TaskStatusChangedEvent = { taskId: id, from, to, assigneeId: task.assigneeId, projectId: task.projectId, title: task.title };
    this.bus.publish('task.statusChanged', event);
    return task;
  }

  assign(id: string, assigneeId: string): Task | undefined {
    const task = this.tasks.get(id);
    if (!task) return undefined;
    task.assigneeId = assigneeId;
    const event: TaskAssignedEvent = { taskId: id, assigneeId, projectId: task.projectId, title: task.title };
    this.bus.publish('task.assigned', event);
    return task;
  }

  private isValidTransition(from: TaskStatus, to: TaskStatus): boolean {
    const order: TaskStatus[] = ['todo', 'in-progress', 'done'];
    const fromIdx = order.indexOf(from);
    const toIdx = order.indexOf(to);
    return toIdx === fromIdx || toIdx === fromIdx + 1; // allow idempotent set and forward one step
  }

  private generateId(): string {
    return Math.random().toString(36).slice(2) + Date.now().toString(36);
  }
}

import { EventBus, CommentAddedEvent } from '../event-bus';

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  text: string;
  createdAt: number; // timestamp ms
}

export class CommentService {
  private comments: Map<string, Comment> = new Map();
  private bus: EventBus;

  constructor(bus: EventBus) {
    this.bus = bus;
  }

  list(filter?: { taskId?: string }): Comment[] {
    let arr = Array.from(this.comments.values());
    if (filter?.taskId) arr = arr.filter((c) => c.taskId === filter.taskId);
    return arr;
  }

  get(id: string): Comment | undefined {
    return this.comments.get(id);
  }

  create(input: { taskId: string; authorId: string; text: string }): Comment {
    const id = this.generateId();
    const comment: Comment = { id, taskId: input.taskId, authorId: input.authorId, text: input.text, createdAt: Date.now() };
    this.comments.set(id, comment);
    const event: CommentAddedEvent = { commentId: id, taskId: comment.taskId, authorId: comment.authorId, text: comment.text };
    this.bus.publish('comment.added', event);
    return comment;
  }

  delete(id: string): boolean {
    return this.comments.delete(id);
  }

  private generateId(): string {
    return Math.random().toString(36).slice(2) + Date.now().toString(36);
  }
}

import { EventBus, TaskAssignedEvent, TaskStatusChangedEvent, CommentAddedEvent, TaskCreatedEvent, TaskDeletedEvent } from '../event-bus';

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  timestamp: number;
}

export class NotificationService {
  private notifications: Map<string, Notification> = new Map();

  constructor(private bus: EventBus) {
    // Subscribe to events
    this.bus.subscribe<TaskAssignedEvent>('task.assigned', (e) => this.onTaskAssigned(e));
    this.bus.subscribe<TaskStatusChangedEvent>('task.statusChanged', (e) => this.onTaskStatusChanged(e));
    this.bus.subscribe<CommentAddedEvent>('comment.added', (e) => this.onCommentAdded(e));
    this.bus.subscribe<TaskCreatedEvent>('task.created', (e) => this.onTaskCreated(e));
    this.bus.subscribe<TaskDeletedEvent>('task.deleted', (e) => this.onTaskDeleted(e));
  }

  private onTaskAssigned(e: TaskAssignedEvent) {
    this.create({ userId: e.assigneeId, message: `You were assigned task '${e.title}' in project ${e.projectId}` });
  }

  private onTaskStatusChanged(e: TaskStatusChangedEvent) {
    if (e.assigneeId) {
      this.create({ userId: e.assigneeId, message: `Task '${e.title}' status changed ${e.from} -> ${e.to}` });
    }
  }

  private onCommentAdded(e: CommentAddedEvent) {
    // In a real app, we'd lookup task assignee; here we can't call TaskService directly.
    // So we publish notifications based on a simple convention: another component (router)
    // may echo task info to events. For now, we'll just record a general comment event
    // that can be filtered by user later if extended. To stay within constraints, we'll
    // not notify specific users here unless the router publishes an enriched event.
    // We'll subscribe also for an enriched event name 'comment.added.enriched'
  }

  private onTaskCreated(e: TaskCreatedEvent) {
    if (e.assigneeId) {
      this.create({ userId: e.assigneeId, message: `You have a new assigned task '${e.title}'` });
    }
  }

  private onTaskDeleted(e: TaskDeletedEvent) {
    if (e.assigneeId) {
      this.create({ userId: e.assigneeId, message: `Task '${e.title}' was deleted` });
    }
  }

  list(filter?: { userId?: string }): Notification[] {
    let arr = Array.from(this.notifications.values());
    if (filter?.userId) arr = arr.filter((n) => n.userId === filter.userId);
    arr.sort((a, b) => a.timestamp - b.timestamp);
    return arr;
  }

  get(id: string): Notification | undefined {
    return this.notifications.get(id);
  }

  create(input: { userId: string; message: string }): Notification {
    const id = this.generateId();
    const notification: Notification = { id, userId: input.userId, message: input.message, read: false, timestamp: Date.now() };
    this.notifications.set(id, notification);
    return notification;
  }

  markRead(id: string): Notification | undefined {
    const n = this.notifications.get(id);
    if (!n) return undefined;
    n.read = true;
    return n;
  }

  private generateId(): string {
    return Math.random().toString(36).slice(2) + Date.now().toString(36);
  }
}

import { IncomingMessage, ServerResponse } from 'http';
import { parse as parseUrl } from 'url';
import { EventBus } from './event-bus';
import { UserService } from './services/user-service';
import { ProjectService } from './services/project-service';
import { TaskService } from './services/task-service';
import { CommentService } from './services/comment-service';
import { NotificationService } from './services/notification-service';

export class ApiRouter {
  constructor(
    private bus: EventBus,
    private users: UserService,
    private projects: ProjectService,
    private tasks: TaskService,
    private comments: CommentService,
    private notifications: NotificationService
  ) {}

  async handle(req: IncomingMessage, res: ServerResponse) {
    const url = parseUrl(req.url || '', true);
    const method = req.method || 'GET';
    const path = url.pathname || '/';

    // Helper functions
    const readBody = async () => {
      const chunks: Buffer[] = [];
      for await (const chunk of req) chunks.push(Buffer.from(chunk));
      const raw = Buffer.concat(chunks).toString('utf-8');
      if (!raw) return undefined as any;
      try { return JSON.parse(raw); } catch { return undefined as any; }
    };

    const send = (code: number, data?: any) => {
      const body = data !== undefined ? JSON.stringify(data) : '';
      res.statusCode = code;
      res.setHeader('Content-Type', 'application/json');
      res.end(body);
    };

    try {
      // Users
      if (path === '/users' && method === 'GET') return send(200, this.users.list());
      if (path === '/users' && method === 'POST') {
        const body = await readBody();
        const user = this.users.create({ name: body?.name, email: body?.email });
        return send(201, user);
      }
      const userIdMatch = path.match(/^\/users\/(.+)$/);
      if (userIdMatch) {
        const id = userIdMatch[1];
        if (method === 'GET') {
          const user = this.users.get(id);
          return user ? send(200, user) : send(404, { error: 'Not found' });
        }
        if (method === 'PUT') {
          const body = await readBody();
          const updated = this.users.update(id, body || {});
          return updated ? send(200, updated) : send(404, { error: 'Not found' });
        }
        if (method === 'DELETE') {
          const ok = this.users.delete(id);
          return send(ok ? 204 : 404);
        }
      }

      // Projects
      if (path === '/projects' && method === 'GET') return send(200, this.projects.list());
      if (path === '/projects' && method === 'POST') {
        const body = await readBody();
        const project = this.projects.create({ name: body?.name, description: body?.description, members: body?.members });
        return send(201, project);
      }
      const projectIdMembersMatch = path.match(/^\/projects\/([^\/]+)\/members$/);
      if (projectIdMembersMatch) {
        const id = projectIdMembersMatch[1];
        const body = await readBody();
        if (method === 'POST') {
          const updated = this.projects.addMember(id, body?.userId);
          return updated ? send(200, updated) : send(404, { error: 'Not found' });
        }
        if (method === 'DELETE') {
          const updated = this.projects.removeMember(id, body?.userId);
          return updated ? send(200, updated) : send(404, { error: 'Not found' });
        }
      }
      const projectIdMatch = path.match(/^\/projects\/([^\/]+)$/);
      if (projectIdMatch) {
        const id = projectIdMatch[1];
        if (method === 'GET') {
          const project = this.projects.get(id);
          return project ? send(200, project) : send(404, { error: 'Not found' });
        }
        if (method === 'PUT') {
          const body = await readBody();
          const updated = this.projects.update(id, body || {});
          return updated ? send(200, updated) : send(404, { error: 'Not found' });
        }
        if (method === 'DELETE') {
          const ok = this.projects.delete(id);
          return send(ok ? 204 : 404);
        }
      }

      // Tasks
      if (path === '/tasks' && method === 'GET') {
        const projectId = (url.query.projectId as string) || undefined;
        return send(200, this.tasks.list({ projectId }));
      }
      if (path === '/tasks' && method === 'POST') {
        const body = await readBody();
        const task = this.tasks.create({ title: body?.title, description: body?.description, assigneeId: body?.assigneeId, projectId: body?.projectId });
        return send(201, task);
      }
      const taskStatusMatch = path.match(/^\/tasks\/([^\/]+)\/status$/);
      if (taskStatusMatch && method === 'PUT') {
        const id = taskStatusMatch[1];
        const body = await readBody();
        const updated = this.tasks.setStatus(id, body?.status);
        return updated ? send(200, updated) : send(400, { error: 'Invalid status transition or task not found' });
      }
      const taskAssignMatch = path.match(/^\/tasks\/([^\/]+)\/assign$/);
      if (taskAssignMatch && method === 'PUT') {
        const id = taskAssignMatch[1];
        const body = await readBody();
        const updated = this.tasks.assign(id, body?.assigneeId);
        return updated ? send(200, updated) : send(404, { error: 'Task not found' });
      }
      const taskIdMatch = path.match(/^\/tasks\/([^\/]+)$/);
      if (taskIdMatch) {
        const id = taskIdMatch[1];
        if (method === 'GET') {
          const task = this.tasks.get(id);
          return task ? send(200, task) : send(404, { error: 'Not found' });
        }
        if (method === 'PUT') {
          const body = await readBody();
          const updated = this.tasks.update(id, body || {});
          return updated ? send(200, updated) : send(404, { error: 'Not found' });
        }
        if (method === 'DELETE') {
          const ok = this.tasks.delete(id);
          return send(ok ? 204 : 404);
        }
      }

      // Comments
      if (path === '/comments' && method === 'GET') {
        const taskId = (url.query.taskId as string) || undefined;
        return send(200, this.comments.list({ taskId }));
      }
      if (path === '/comments' && method === 'POST') {
        const body = await readBody();
        const comment = this.comments.create({ taskId: body?.taskId, authorId: body?.authorId, text: body?.text });
        return send(201, comment);
      }
      const commentIdMatch = path.match(/^\/comments\/([^\/]+)$/);
      if (commentIdMatch) {
        const id = commentIdMatch[1];
        if (method === 'GET') {
          const c = this.comments.get(id);
          return c ? send(200, c) : send(404, { error: 'Not found' });
        }
        if (method === 'DELETE') {
          const ok = this.comments.delete(id);
          return send(ok ? 204 : 404);
        }
      }

      // Notifications
      if (path === '/notifications' && method === 'GET') {
        const userId = (url.query.userId as string) || undefined;
        return send(200, this.notifications.list({ userId }));
      }
      const notifIdMatch = path.match(/^\/notifications\/([^\/]+)\/read$/);
      if (notifIdMatch && method === 'PUT') {
        const id = notifIdMatch[1];
        const n = this.notifications.markRead(id);
        return n ? send(200, n) : send(404, { error: 'Not found' });
      }

      return send(404, { error: 'Route not found' });
    } catch (err: any) {
      return send(500, { error: err?.message || 'Internal error' });
    }
  }
}

import http from 'http';
import { EventBus } from './event-bus';
import { UserService } from './services/user-service';
import { ProjectService } from './services/project-service';
import { TaskService } from './services/task-service';
import { CommentService } from './services/comment-service';
import { NotificationService } from './services/notification-service';
import { ApiRouter } from './router';

const bus = new EventBus();

const userService = new UserService();
const projectService = new ProjectService();
const taskService = new TaskService(bus);
const commentService = new CommentService(bus);
const notificationService = new NotificationService(bus);

const router = new ApiRouter(bus, userService, projectService, taskService, commentService, notificationService);

const server = http.createServer((req, res) => router.handle(req, res));

const PORT = process.env.PORT ? parseInt(process.env.PORT, 10) : 3000;
server.listen(PORT, () => {
  console.log(`Task Management API server listening on http://localhost:${PORT}`);
});

import { spawn } from 'child_process';
import http from 'http';

function request(method: string, path: string, body?: any): Promise<any> {
  return new Promise((resolve, reject) => {
    const data = body ? JSON.stringify(body) : undefined;
    const req = http.request(
      { hostname: 'localhost', port: 3000, path, method, headers: { 'Content-Type': 'application/json', 'Content-Length': data ? Buffer.byteLength(data) : 0 } },
      (res) => {
        const chunks: Buffer[] = [];
        res.on('data', (c) => chunks.push(c as Buffer));
        res.on('end', () => {
          const raw = Buffer.concat(chunks).toString('utf-8');
          try {
            resolve(raw ? JSON.parse(raw) : undefined);
          } catch (e) {
            reject(e);
          }
        });
      }
    );
    req.on('error', reject);
    if (data) req.write(data);
    req.end();
  });
}

async function runDemo() {
  console.log('Starting server...');
  const serverProc = spawn('node', ['-e', "import('tsx').then(()=>import('./src/main.ts'))"], { stdio: 'inherit', shell: true });
  await new Promise((r) => setTimeout(r, 1000));

  // Create users
  const alice = await request('POST', '/users', { name: 'Alice', email: 'alice@example.com' });
  const bob = await request('POST', '/users', { name: 'Bob', email: 'bob@example.com' });
  console.log('Users:', await request('GET', '/users'));

  // Create project
  const project = await request('POST', '/projects', { name: 'Project A', description: 'Demo project' });
  await request('POST', `/projects/${project.id}/members`, { userId: alice.id });
  await request('POST', `/projects/${project.id}/members`, { userId: bob.id });
  console.log('Project:', await request('GET', `/projects/${project.id}`));

  // Create task
  const task1 = await request('POST', '/tasks', { title: 'Setup repo', description: 'Initialize repository', projectId: project.id, assigneeId: alice.id });
  const task2 = await request('POST', '/tasks', { title: 'Write docs', description: 'Documentation', projectId: project.id });
  console.log('Tasks in project:', await request('GET', `/tasks?projectId=${project.id}`));

  // Assign and progress task
  await request('PUT', `/tasks/${task2.id}/assign`, { assigneeId: bob.id });
  await request('PUT', `/tasks/${task1.id}/status`, { status: 'in-progress' });
  await request('PUT', `/tasks/${task1.id}/status`, { status: 'done' });

  // Comments
  const c1 = await request('POST', '/comments', { taskId: task1.id, authorId: bob.id, text: 'Great job!' });
  const c2 = await request('POST', '/comments', { taskId: task2.id, authorId: alice.id, text: 'Please add more details.' });
  console.log('Comments for task1:', await request('GET', `/comments?taskId=${task1.id}`));

  // Notifications
  console.log('Notifications for Alice:', await request('GET', `/notifications?userId=${alice.id}`));
  console.log('Notifications for Bob:', await request('GET', `/notifications?userId=${bob.id}`));

  // Mark first notification read for Alice (if any)
  const aliceNotifs = await request('GET', `/notifications?userId=${alice.id}`);
  if (aliceNotifs[0]) {
    await request('PUT', `/notifications/${aliceNotifs[0].id}/read`);
    console.log('After marking read:', await request('GET', `/notifications?userId=${alice.id}`));
  }

  // Shutdown server
  serverProc.kill('SIGINT');
}

runDemo().catch((err) => {
  console.error('Demo error:', err);
  process.exit(1);
});

