export type EventHandler<T = any> = (payload: T) => void;

export class EventBus {
  private subscribers: Map<string, Set<EventHandler>> = new Map();

  subscribe<T = any>(eventName: string, handler: EventHandler<T>): () => void {
    if (!this.subscribers.has(eventName)) {
      this.subscribers.set(eventName, new Set());
    }
    const set = this.subscribers.get(eventName)!;
    set.add(handler as EventHandler);
    return () => {
      set.delete(handler as EventHandler);
    };
  }

  publish<T = any>(eventName: string, payload: T): void {
    const set = this.subscribers.get(eventName);
    if (!set) return;
    for (const handler of set) {
      try {
        handler(payload);
      } catch (err) {
        // Swallow handler errors to avoid breaking the bus
        console.error(`Error in handler for event '${eventName}':`, err);
      }
    }
  }
}

export type TaskStatus = 'todo' | 'in-progress' | 'done';

// Event payload types (for convenience across services)
export interface TaskAssignedEvent {
  taskId: string;
  assigneeId: string;
  projectId: string;
  title: string;
}

export interface TaskStatusChangedEvent {
  taskId: string;
  from: TaskStatus;
  to: TaskStatus;
  assigneeId?: string;
  projectId: string;
  title: string;
}

export interface TaskDeletedEvent {
  taskId: string;
  assigneeId?: string;
  projectId: string;
  title: string;
}

export interface TaskCreatedEvent {
  taskId: string;
  projectId: string;
  assigneeId?: string;
  title: string;
}

export interface CommentAddedEvent {
  commentId: string;
  taskId: string;
  authorId: string;
  text: string;
}

export interface CommentAddedEnrichedEvent extends CommentAddedEvent {
  taskAssigneeId?: string;
}

import { EventBus, TaskAssignedEvent, TaskStatusChangedEvent, CommentAddedEvent, TaskCreatedEvent, TaskDeletedEvent, CommentAddedEnrichedEvent } from '../event-bus';

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  timestamp: number;
}

export class NotificationService {
  private notifications: Map<string, Notification> = new Map();

  constructor(private bus: EventBus) {
    // Subscribe to events
    this.bus.subscribe<TaskAssignedEvent>('task.assigned', (e) => this.onTaskAssigned(e));
    this.bus.subscribe<TaskStatusChangedEvent>('task.statusChanged', (e) => this.onTaskStatusChanged(e));
    this.bus.subscribe<CommentAddedEvent>('comment.added', (e) => this.onCommentAdded(e));
    this.bus.subscribe<CommentAddedEnrichedEvent>('comment.added.enriched', (e) => this.onCommentAddedEnriched(e));
    this.bus.subscribe<TaskCreatedEvent>('task.created', (e) => this.onTaskCreated(e));
    this.bus.subscribe<TaskDeletedEvent>('task.deleted', (e) => this.onTaskDeleted(e));
  }

  private onTaskAssigned(e: TaskAssignedEvent) {
    this.create({ userId: e.assigneeId, message: `You were assigned task '${e.title}' in project ${e.projectId}` });
  }

  private onTaskStatusChanged(e: TaskStatusChangedEvent) {
    if (e.assigneeId) {
      this.create({ userId: e.assigneeId, message: `Task '${e.title}' status changed ${e.from} -> ${e.to}` });
    }
  }

  private onCommentAdded(_e: CommentAddedEvent) {
    // noop unless enriched event is used
  }

  private onCommentAddedEnriched(e: CommentAddedEnrichedEvent) {
    if (e.taskAssigneeId && e.taskAssigneeId !== e.authorId) {
      this.create({ userId: e.taskAssigneeId, message: `New comment on your task: "${e.text}"` });
    }
  }

  private onTaskCreated(e: TaskCreatedEvent) {
    if (e.assigneeId) {
      this.create({ userId: e.assigneeId, message: `You have a new assigned task '${e.title}'` });
    }
  }

  private onTaskDeleted(e: TaskDeletedEvent) {
    if (e.assigneeId) {
      this.create({ userId: e.assigneeId, message: `Task '${e.title}' was deleted` });
    }
  }

  list(filter?: { userId?: string }): Notification[] {
    let arr = Array.from(this.notifications.values());
    if (filter?.userId) arr = arr.filter((n) => n.userId === filter.userId);
    arr.sort((a, b) => a.timestamp - b.timestamp);
    return arr;
  }

  get(id: string): Notification | undefined {
    return this.notifications.get(id);
  }

  create(input: { userId: string; message: string }): Notification {
    const id = this.generateId();
    const notification: Notification = { id, userId: input.userId, message: input.message, read: false, timestamp: Date.now() };
    this.notifications.set(id, notification);
    return notification;
  }

  markRead(id: string): Notification | undefined {
    const n = this.notifications.get(id);
    if (!n) return undefined;
    n.read = true;
    return n;
  }

  private generateId(): string {
    return Math.random().toString(36).slice(2) + Date.now().toString(36);
  }
}

import { EventBus, TaskStatus, TaskAssignedEvent, TaskStatusChangedEvent, TaskCreatedEvent, TaskDeletedEvent, CommentAddedEvent, CommentAddedEnrichedEvent } from '../event-bus';

export interface Task {
  id: string;
  title: string;
  description?: string;
  status: TaskStatus;
  assigneeId?: string; // user ID
  projectId: string;
}

export class TaskService {
  private tasks: Map<string, Task> = new Map();
  private bus: EventBus;

  constructor(bus: EventBus) {
    this.bus = bus;

    // Listen for comments to enrich with assignee info
    this.bus.subscribe<CommentAddedEvent>('comment.added', (e) => {
      const task = this.tasks.get(e.taskId);
      const enriched: CommentAddedEnrichedEvent = {
        ...e,
        taskAssigneeId: task?.assigneeId,
      };
      this.bus.publish('comment.added.enriched', enriched);
    });
  }

  list(filter?: { projectId?: string }): Task[] {
    let arr = Array.from(this.tasks.values());
    if (filter?.projectId) arr = arr.filter((t) => t.projectId === filter.projectId);
    return arr;
  }

  get(id: string): Task | undefined {
    return this.tasks.get(id);
  }

  create(input: { title: string; description?: string; assigneeId?: string; projectId: string }): Task {
    const id = this.generateId();
    const task: Task = {
      id,
      title: input.title,
      description: input.description,
      status: 'todo',
      assigneeId: input.assigneeId,
      projectId: input.projectId,
    };
    this.tasks.set(id, task);
    const event: TaskCreatedEvent = { taskId: id, projectId: task.projectId, assigneeId: task.assigneeId, title: task.title };
    this.bus.publish('task.created', event);
    if (task.assigneeId) {
      const assignedEvent: TaskAssignedEvent = { taskId: id, assigneeId: task.assigneeId, projectId: task.projectId, title: task.title };
      this.bus.publish('task.assigned', assignedEvent);
    }
    return task;
  }

  update(id: string, input: Partial<Omit<Task, 'id' | 'status' | 'projectId'>>): Task | undefined {
    const existing = this.tasks.get(id);
    if (!existing) return undefined;
    const updated: Task = { ...existing, ...input, id };
    this.tasks.set(id, updated);
    if (existing.assigneeId !== updated.assigneeId && updated.assigneeId) {
      const assignedEvent: TaskAssignedEvent = { taskId: id, assigneeId: updated.assigneeId, projectId: updated.projectId, title: updated.title };
      this.bus.publish('task.assigned', assignedEvent);
    }
    return updated;
  }

  delete(id: string): boolean {
    const existing = this.tasks.get(id);
    if (!existing) return false;
    this.tasks.delete(id);
    const event: TaskDeletedEvent = { taskId: id, assigneeId: existing.assigneeId, projectId: existing.projectId, title: existing.title };
    this.bus.publish('task.deleted', event);
    return true;
  }

  setStatus(id: string, to: TaskStatus): Task | undefined {
    const task = this.tasks.get(id);
    if (!task) return undefined;
    const from = task.status;
    if (!this.isValidTransition(from, to)) return undefined;
    task.status = to;
    const event: TaskStatusChangedEvent = { taskId: id, from, to, assigneeId: task.assigneeId, projectId: task.projectId, title: task.title };
    this.bus.publish('task.statusChanged', event);
    return task;
  }

  assign(id: string, assigneeId: string): Task | undefined {
    const task = this.tasks.get(id);
    if (!task) return undefined;
    task.assigneeId = assigneeId;
    const event: TaskAssignedEvent = { taskId: id, assigneeId, projectId: task.projectId, title: task.title };
    this.bus.publish('task.assigned', event);
    return task;
  }

  private isValidTransition(from: TaskStatus, to: TaskStatus): boolean {
    const order: TaskStatus[] = ['todo', 'in-progress', 'done'];
    const fromIdx = order.indexOf(from);
    const toIdx = order.indexOf(to);
    return toIdx === fromIdx || toIdx === fromIdx + 1; // allow idempotent set and forward one step
  }

  private generateId(): string {
    return Math.random().toString(36).slice(2) + Date.now().toString(36);
  }
}

